#include "engine/performance_timeline.hpp"
#include "engine/ai_controller.hpp"
#include <iomanip>
#include <sstream>
#include <set>
#include <algorithm>
namespace engine {
std::vector<AiTaskBinding> builtinAiTasks();
namespace {
void require(bool b,const std::string& m){if(!b)throw std::invalid_argument(m);}
void key(std::string_view s){require(!s.empty()&&s.size()<=256,"Invalid AI binding/parameter key");for(unsigned char c:s)require(c>32&&c!=127,"Invalid AI key character");}
void writeBinding(std::ostream& o,const AiBinding& b){o<<std::quoted(b.key)<<' '<<b.parameters.size()<<'\n';for(const auto&[k,v]:b.parameters){o<<std::quoted(k)<<' ';writeAiValue(o,v);o<<'\n';}o<<b.sources.size()<<'\n';for(const auto&[p,k]:b.sources)o<<std::quoted(p)<<' '<<std::quoted(k)<<'\n';}
AiBinding readBinding(std::istream& in,unsigned version){AiBinding b;std::size_t count=0;require(bool(in>>std::quoted(b.key)>>count)&&count<=16,"Invalid AI binding payload");for(std::size_t i=0;i<count;++i){std::string k;require(bool(in>>std::quoted(k)),"Invalid AI parameter");auto v=readAiValue(in);require(b.parameters.emplace(k,std::move(v)).second,"Duplicate AI parameter");}if(version>=2){require(bool(in>>count)&&count<=16,"Invalid AI source count");for(std::size_t i=0;i<count;++i){std::string p,k;require(bool(in>>std::quoted(p)>>std::quoted(k))&&b.sources.emplace(p,k).second,"Invalid AI source");}}return b;}

}
std::shared_ptr<const AiBindingRegistry> AiBindingRegistry::create(std::vector<AiBehaviorBinding> behaviors,std::vector<AiConditionBinding> conditions,std::vector<AiTaskBinding> tasks){
    require(behaviors.size()<=128&&conditions.size()<=128,"AI registry capacity exceeded");std::set<std::string> keys;
    for(const auto& b:behaviors){key(b.key);validateAiSchema(b.parameters);require(keys.insert(b.key).second,"Duplicate AI behavior binding");}keys.clear();
    for(const auto& c:conditions){key(c.key);validateAiSchema(c.parameters);require(keys.insert(c.key).second&&bool(c.evaluate),"Invalid AI condition binding");}
    keys.clear();require(tasks.size()<=128,"AI task registry capacity exceeded");for(const auto& t:tasks){key(t.key);validateAiSchema(t.parameters);require(keys.insert(t.key).second&&bool(t.create),"Invalid AI task binding");}
    auto r=std::shared_ptr<AiBindingRegistry>(new AiBindingRegistry);r->tasks_=std::move(tasks);r->behaviors_=std::move(behaviors);r->conditions_=std::move(conditions);return r;
}
const AiBehaviorBinding& AiBindingRegistry::behavior(std::string_view k)const{for(const auto& b:behaviors_)if(b.key==k)return b;throw std::invalid_argument("Missing AI behavior binding: "+std::string(k));}
const AiConditionBinding& AiBindingRegistry::condition(std::string_view k)const{for(const auto& b:conditions_)if(b.key==k)return b;throw std::invalid_argument("Missing AI condition binding: "+std::string(k));}
AiBinding AiBindingRegistry::defaults(std::string_view k,bool c)const{AiBinding b;b.key=k;const auto& ps=c?condition(k).parameters:behavior(k).parameters;for(const auto& p:ps)b.parameters[p.key]=p.initial;return b;}
void AiBindingRegistry::validate(const AiBinding& b,bool c)const{const auto& ps=c?condition(b.key).parameters:behavior(b.key).parameters;require(ps.size()==b.parameters.size(),"AI parameters do not match binding schema: "+b.key);for(const auto& p:ps){auto it=b.parameters.find(p.key);require(it!=b.parameters.end(),"Missing AI parameter: "+p.key);validateAiValue(p,it->second);}}
std::shared_ptr<const AiBindingRegistry> AiBindingRegistry::builtins(){static auto result=create({
    {"idle",{},false,[](AiControllerComponent& c,const AiBinding&,double){if(auto* m=c.motor())m->stop();}, {},{}},
    {"move",{{"velocity",AiParameterType::Vector,Vec3{1,0,0},-100,100}},true,{},[](AiControllerComponent& c,const AiBinding& b,double){auto* m=c.motor();if(!m)throw std::runtime_error("AI move binding requires a motor");m->submitMovement({std::get<Vec3>(b.parameters.at("velocity")),false});},{}}
},{
    {"always",{},[](AiControllerComponent&,const AiBinding&){return true;}},
    {"flag",{{"value",AiParameterType::Boolean,false}},[](AiControllerComponent&,const AiBinding& b){return std::get<bool>(b.parameters.at("value"));}},
    {"not-flag",{{"value",AiParameterType::Boolean,false}},[](AiControllerComponent&,const AiBinding& b){return !std::get<bool>(b.parameters.at("value"));}},
    {"near",{{"target",AiParameterType::Actor,std::string{}},{"distance",AiParameterType::Number,2.0,0,10000}},[](AiControllerComponent& c,const AiBinding& b){auto* target=c.resolveActor(std::get<std::string>(b.parameters.at("target")));if(!target||!c.owner())return false;auto d=transformPoint(target->worldMatrix(),{})-transformPoint(c.owner()->worldMatrix(),{});auto range=std::get<double>(b.parameters.at("distance"));return double(dot(d,d))<=range*range;}}
},builtinAiTasks());return result;}
AiControllerSettings AiControllerSettings::defaults(std::shared_ptr<const StateMachineDefinition> graph,const AiBindingRegistry& r){require(bool(graph),"Missing controller graph");AiControllerSettings s;s.graph=std::move(graph);for(const auto& state:s.graph->data().states)s.states[state.id]=r.defaults(state.behavior);for(const auto& t:s.graph->data().transitions)s.conditions[t.condition]=r.defaults(t.condition,true);return s;}
void AiControllerSettings::validate(const AiBindingRegistry& r)const{
    require(bool(graph),"Missing controller graph");
    auto binding=[&](const AiBinding& b,bool c){r.validate(b,c);const auto& ps=c?r.condition(b.key).parameters:r.behavior(b.key).parameters;
        for(const auto&[param,field]:b.sources){auto p=std::find_if(ps.begin(),ps.end(),[&](const auto& p){return p.key==param;});const auto& fields=graph->data().blackboard;auto f=std::find_if(fields.begin(),fields.end(),[&](const auto& f){return f.key==field;});require(p!=ps.end()&&f!=fields.end(),"Unknown AI parameter or blackboard source");require(p->type==f->type,"AI source type does not match parameter");if(p->type==AiParameterType::Number||p->type==AiParameterType::Vector)require(f->minimum>=p->minimum&&f->maximum<=p->maximum,"AI source bounds exceed parameter schema");}
    };
    for(const auto& state:graph->data().states){for(const auto& t:state.tasks)r.validateTask(t,*graph);}
    require(states.size()==graph->data().states.size(),"Controller state bindings do not match graph");std::set<std::string> keys;for(const auto& s:graph->data().states){auto it=states.find(s.id);require(it!=states.end(),"Missing controller state binding");binding(it->second,false);}for(const auto& t:graph->data().transitions)keys.insert(t.condition);require(keys.size()==conditions.size(),"Controller condition bindings do not match graph");for(const auto& k:keys){auto it=conditions.find(k);require(it!=conditions.end(),"Missing controller condition binding: "+k);binding(it->second,true);}
    for(const auto& leaf:graph->data().states){unsigned writers=0;for(auto id:graph->entryPath(leaf.id)){const auto& state=graph->state(id);writers+=r.behavior(states.at(id).key).needsMotor;bool motorTask=false;for(const auto& t:state.tasks)motorTask|=r.task(t.key).needsMotor;writers+=motorTask;}require(writers<=1,"Competing AI motor/pose writers in active hierarchy");}

}

AiControllerComponent::AiControllerComponent(std::string name,AiControllerSettings settings,std::shared_ptr<const AiBindingRegistry> registry):Component(std::move(name)),settings_(std::move(settings)),registry_(std::move(registry)){require(bool(registry_),"Missing AI binding registry");settings_.validate(*registry_);machine_=std::make_unique<StateMachine>(settings_.graph);for(const auto& f:settings_.graph->data().blackboard)blackboard_[f.key]=f.initial;setFixedTickEnabled(true);}
CharacterMotorComponent* AiControllerComponent::motor()const{return const_cast<CharacterMotorComponent*>(getComponent<CharacterMotorComponent>());}
Actor* AiControllerComponent::resolveActor(std::string_view id)const{if(!scene()||id.empty())return nullptr;auto* a=dynamic_cast<Actor*>(const_cast<Scene*>(scene())->findSavedNode(id));return a&&a->isActiveInHierarchy()?a:nullptr;}
void AiControllerComponent::validateReferences(const Scene& scene)const{for(const auto& state:settings_.graph->data().states)for(const auto& task:state.tasks)for(const auto&[k,v]:task.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI task actor reference: "+*id);for(const auto& e:settings_.graph->data().events)for(const auto& p:e.parameters)if(auto* id=std::get_if<std::string>(&p.initial);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI event default actor reference: "+*id);for(const auto& f:settings_.graph->data().blackboard)if(auto* id=std::get_if<std::string>(&f.initial);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing blackboard actor reference: "+*id);for(const auto* map:{&settings_.conditions})for(const auto&[k,b]:*map)for(const auto&[p,v]:b.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI actor reference: "+*id);for(const auto&[k,b]:settings_.states)for(const auto&[p,v]:b.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI actor reference: "+*id);}
void AiControllerComponent::validate()const{Component::validate();settings_.validate(*registry_);if(!owner()){require(!scene(),"AI controller requires an actor owner");return;}require(parent()==owner(),"AI controllers must be direct actor components");require(owner()->getComponents<AiControllerComponent>().size()==1,"Only one AI controller may own an actor");for(const auto& s:settings_.graph->data().states)for(const auto& t:s.tasks)if(registry_->task(t.key).needsMotor)require(motor()!=nullptr,"AI task requires a CharacterMotorComponent");for(const auto&[id,b]:settings_.states)if(registry_->behavior(b.key).needsMotor){require(motor()!=nullptr,"AI movement requires a CharacterMotorComponent");auto resolvedBinding=resolved(b,blackboard_);if(auto it=resolvedBinding.parameters.find("velocity");it!=resolvedBinding.parameters.end()&&motor()->settings().collisionAware)if(auto* v=std::get_if<Vec3>(&it->second))require(v->y==0,"Collision-aware AI velocity must have Y=0");}}
AiBinding AiControllerComponent::resolved(const AiBinding& binding,const std::map<std::string,AiValue>& values)const{auto result=binding;for(const auto&[p,k]:binding.sources)result.parameters.at(p)=values.at(k);return result;}
const AiValue& AiControllerComponent::blackboardValue(std::string_view k)const{return blackboard_.at(std::string(k));}
void AiControllerComponent::setBlackboard(const std::map<std::string,AiValue>& patch){
    auto next=blackboard_;for(const auto&[k,v]:patch){const auto& fields=settings_.graph->data().blackboard;auto f=std::find_if(fields.begin(),fields.end(),[&](const auto& f){return f.key==k;});require(f!=fields.end(),"Unknown blackboard field: "+k);validateAiValue(*f,v);if(auto* id=std::get_if<std::string>(&v);scene()&&id&&!id->empty())require(dynamic_cast<const Actor*>(scene()->findSavedNode(*id))!=nullptr,"Missing blackboard actor");next.at(k)=v;}
    if(auto* m=motor();m&&m->settings().collisionAware)for(const auto&[id,b]:settings_.states)if(registry_->behavior(b.key).needsMotor){auto r=resolved(b,next);if(auto it=r.parameters.find("velocity");it!=r.parameters.end())if(auto* v=std::get_if<Vec3>(&it->second))require(v->y==0,"Collision-aware AI velocity must have Y=0");}
    blackboard_=std::move(next);
}
bool AiControllerComponent::postEvent(AiEvent event,std::optional<AiEventScope> scope){settings_.graph->validateEvent(event);if(scene())for(const auto&[k,v]:event.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene()->findSavedNode(*id))!=nullptr,"Missing AI event actor");return machine_->postEvent(std::move(event),scope);}
void AiControllerComponent::configure(AiControllerSettings settings){require(!machine_->executing(),"Cannot configure AI from a runtime callback");settings.validate(*registry_);auto next=std::make_unique<StateMachine>(settings.graph);auto old=settings_;auto oldValues=blackboard_;std::map<std::string,AiValue> defaults;for(const auto& f:settings.graph->data().blackboard)defaults[f.key]=f.initial;settings_=settings;blackboard_=defaults;try{validate();if(scene())validateReferences(*scene());}catch(...){settings_=std::move(old);blackboard_=std::move(oldValues);throw;}settings_=std::move(old);blackboard_=std::move(oldValues);stop();settings_=std::move(settings);blackboard_=std::move(defaults);machine_=std::move(next);transitions_.clear();taskHistory_.clear();simulationSeconds_=0;error_.clear();}

void AiControllerComponent::stop()noexcept{if(machine_->executing()){stopRequested_=true;if(auto* m=motor())m->stop();return;}stopRequested_=false;try{machine_->stop(*this);}catch(...){}for(auto&[id,run]:taskRuns_)if(run.task)run.task->cancel(*this);taskRuns_.clear();stopRequested_=false;if(auto* m=motor())m->stop();}
void AiControllerComponent::restart(){validate();if(scene())validateReferences(*scene());machine_->restart(*this,settings_.graph,settings_.graph->data().initial);error_.clear();transitions_.clear();taskHistory_.clear();simulationSeconds_=0;}
void AiControllerComponent::transitioned(const AiTransition& t,std::uint32_t from,std::uint32_t to){if(transitions_.size()==32)transitions_.erase(transitions_.begin());transitions_.push_back({from,to,simulationSeconds_,t.condition,t.id,t.from,t.to,currentEvent()?currentEvent()->key:std::string{},machine_->currentEventSequence()});}
void AiControllerComponent::enter(const AiState& s){if(!s.tasks.empty()){TaskRun run;run.scope=eventScope(s.id);taskRuns_.emplace(s.id,std::move(run));}const auto b=resolved(settings_.states.at(s.id),blackboard_);auto& entry=registry_->behavior(b.key);if(entry.enter)entry.enter(*this,b,0);}
void AiControllerComponent::update(const AiState& s,double dt){
    ProfileScope profile(ProfileCategory::AI,"AI state update",s.name);const auto b=resolved(settings_.states.at(s.id),blackboard_);const auto& entry=registry_->behavior(b.key);if(entry.update)entry.update(*this,b,dt);if(isActiveInHierarchy())updateTasks(s,dt);}
void AiControllerComponent::exit(const AiState& s)noexcept{cancelTasks(s.id);try{const auto b=resolved(settings_.states.at(s.id),blackboard_);const auto& entry=registry_->behavior(b.key);if(entry.exit)entry.exit(*this,b,0);}catch(...){error_="AI exit callback failed";}if(auto* m=motor())m->stop();}
bool AiControllerComponent::condition(std::string_view k){const auto b=resolved(settings_.conditions.at(std::string(k)),blackboard_);return registry_->condition(b.key).evaluate(*this,b);}
void AiControllerComponent::fixedTick(double dt){
    ProfileScope profile(ProfileCategory::AI,"AI controller",owner()?owner()->name:name);try{validate();simulationSeconds_+=dt;machine_->step(*this,dt);if(stopRequested_||!isActiveInHierarchy())stop();}catch(const std::exception& e){error_=e.what();stop();}}
std::string AiControllerArchive::save(const AiControllerSettings& s){require(bool(s.graph),"Missing AI graph");std::ostringstream out;out.imbue(std::locale::classic());out<<std::setprecision(17)<<"AIC 2\n"<<std::quoted(StateMachineArchive::save(*s.graph))<<'\n'<<s.states.size()<<' '<<s.conditions.size()<<'\n';for(const auto&[id,b]:s.states){out<<id<<' ';writeBinding(out,b);}for(const auto&[k,b]:s.conditions){out<<std::quoted(k)<<' ';writeBinding(out,b);}auto bytes=out.str();require(bytes.size()<=2097152,"AI controller payload exceeds 2 MiB");return bytes;}
AiControllerSettings AiControllerArchive::load(std::string_view bytes,const AiBindingRegistry& r){require(bytes.size()<=2097152,"AI controller payload exceeds 2 MiB");std::istringstream in{std::string(bytes)};in.imbue(std::locale::classic());std::string magic,graph;unsigned version;std::size_t ns,nc;require(bool(in>>magic>>version>>std::quoted(graph))&&magic=="AIC"&&(version==1||version==2),"Invalid AI controller payload");AiControllerSettings s;s.graph=StateMachineArchive::load(graph);require(bool(in>>ns>>nc)&&ns<=256&&nc<=1024,"Invalid controller binding counts");for(std::size_t i=0;i<ns;++i){std::uint32_t id;require(bool(in>>id),"Invalid controller state ID");require(s.states.emplace(id,readBinding(in,version)).second,"Duplicate controller state binding");}for(std::size_t i=0;i<nc;++i){std::string k;require(bool(in>>std::quoted(k)),"Invalid controller condition");require(s.conditions.emplace(k,readBinding(in,version)).second,"Duplicate controller condition binding");}in>>std::ws;require(in.eof(),"Unexpected controller payload suffix");s.validate(r);return s;}
ComponentCodecs aiControllerCodecs(std::shared_ptr<const AiBindingRegistry> registry){require(bool(registry),"Missing controller codec registry");ComponentCodecs codecs;codecs.add({"engine.ai.controller",typeid(AiControllerComponent),1,[](const Component& c){const auto& ai=dynamic_cast<const AiControllerComponent&>(c);ai.validate();if(ai.scene())ai.validateReferences(*ai.scene());const auto text=AiControllerArchive::save(ai.settings());return std::vector<std::byte>(reinterpret_cast<const std::byte*>(text.data()),reinterpret_cast<const std::byte*>(text.data()+text.size()));},[registry](std::uint32_t version,std::span<const std::byte> bytes){require(version==1,"Unsupported AI controller codec");return std::make_unique<AiControllerComponent>("AI controller",AiControllerArchive::load(std::string_view(reinterpret_cast<const char*>(bytes.data()),bytes.size()),*registry),registry);},[](Component& c,Scene& s){auto& ai=dynamic_cast<AiControllerComponent&>(c);ai.validate();ai.validateReferences(s);}});return codecs;}
} // namespace engine
